{
  "name": "opencode-plugins",
  "version": "1.0.0",
  "description": "Sidebar plugins for OpenCode V2: quota-bars and context-mosaic",
  "type": "module",
  "license": "MIT",
  "exports": {
    "./quota-bars": "./quota-bars/index.ts",
    "./quota-bars/tui": "./quota-bars/tui.tsx",
    "./context-mosaic": "./context-mosaic/index.ts",
    "./context-mosaic/tui": "./context-mosaic/tui.tsx"
  }
}

{
  "name": "opencode-context-mosaic",
  "version": "1.1.0",
  "type": "module",
  "license": "MIT",
  "description": "Sidebar grid of context-occupancy squares (system, tools, MCP, prompts, results, replies, free)",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx",
    "./rpc": "./rpc.ts"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.0"
  }
}

{
  "name": "opencode-quota-bars",
  "version": "1.0.0",
  "description": "OpenCode Go usage-limit bars in the TUI sidebar",
  "type": "module",
  "license": "MIT",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx"
  },
  "dependencies": {
    "@opencode/plugin": "latest"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.0"
  }
}
